//! The frozen certificate, from both sides.
//!
//! `spec/v1/vectors/hcc/tiny-optimal.hex` is a certificate written by hand,
//! annotated byte by byte, and generated by neither implementation. Three
//! things are asserted about it here, and each would catch a different kind of
//! drift:
//!
//! - the solver's writer produces exactly those bytes, so the encoding cannot
//!   change without the vector changing;
//! - the solver's reader accepts them and recovers the records, so the writer
//!   and reader agree about a stream neither produced;
//! - the verifier's reader, which shares nothing with either, accepts them and
//!   recovers the same records.
//!
//! The test lives on this side of the boundary for the reason the cross-parser
//! differential does: a caller may use the verifier's public interface, and the
//! verifier may use nothing.

use hc_cert::assemble::model_hash;
use hc_cert::hcc::{Certificate, ClaimKind, Record};
use hc_cert::read::decode;
use hc_exact::Rational;
use hc_io::mps::{Form, read};

const VECTOR: &str = include_str!("../../../spec/v1/vectors/hcc/tiny-optimal.hex");
const INSTANCE: &[u8] = include_bytes!("../../../spec/v1/vectors/mps/tiny.mps");

/// Strips the annotation from a hexadecimal vector.
///
/// Written here rather than borrowed from the verifier, because a test of two
/// independent implementations that shares a helper between them has one fewer
/// independent implementation than it claims.
fn frozen() -> Vec<u8> {
    let mut out = Vec::new();
    for line in VECTOR.lines() {
        let body = line.split('#').next().unwrap_or_default();
        for token in body.split_whitespace() {
            out.push(u8::from_str_radix(token, 16).expect("the vector is hexadecimal"));
        }
    }
    out
}

fn number(value: i64) -> Rational {
    Rational::from_i64(value)
}

/// The certificate the vector documents, built from its parts.
fn documented() -> Certificate {
    let model = read(INSTANCE, Form::Fixed).expect("the frozen instance parses");
    let records = vec![
        Record::Root {
            node: 0,
            model: model_hash(&model),
        },
        Record::DualBound {
            node: 0,
            terms: vec![(0, number(1))],
        },
        Record::Incumbent {
            reduced: vec![number(4)],
            original: vec![number(4)],
            objective: number(-4),
        },
        Record::Claim {
            kind: ClaimKind::Optimal,
            objective: Some(number(-4)),
            lower: None,
            gap: None,
        },
    ];
    Certificate {
        format_tag: 1,
        instance_bytes: INSTANCE.len() as u64,
        digest: *model.digest(),
        claim: ClaimKind::Optimal,
        records: Certificate::terminated(records),
    }
}

#[test]
fn the_writer_reproduces_the_frozen_bytes() {
    assert_eq!(documented().encode(), frozen());
}

#[test]
fn the_solver_reader_accepts_the_frozen_bytes() {
    let certificate = decode(&frozen()).expect("the frozen vector is accepted");
    assert_eq!(certificate, documented());
}

#[test]
fn the_model_hash_in_the_vector_is_the_hash_of_the_frozen_dump() {
    let model = read(INSTANCE, Form::Fixed).expect("the frozen instance parses");
    let Record::Root { model: stated, .. } = documented().records[0] else {
        panic!("the first record is the root");
    };
    assert_eq!(stated, model_hash(&model));
    // The dump the hash is taken over is itself a frozen asset, so the hash is
    // pinned by two files that would have to be edited together to drift.
    let frozen_dump = include_str!("../../../spec/v1/vectors/mps/tiny.canon");
    assert_eq!(model.canonical_dump(), frozen_dump);
}

#[test]
fn the_verifier_reads_the_same_records_from_the_same_bytes() {
    use hc_verify::vhcc::{Claim, Step, read as read_proof};

    let bytes = frozen();
    let proof = read_proof(&bytes, INSTANCE).expect("the verifier accepts the frozen vector");
    assert_eq!(proof.claim, Claim::Optimal);
    assert_eq!(proof.steps.len(), documented().records.len());

    let Some(Step::Root { stated_hash, .. }) = proof.at(0) else {
        panic!("the verifier's first record is the root");
    };
    let Record::Root { model: ours, .. } = documented().records[0] else {
        panic!("the writer's first record is the root");
    };
    assert_eq!(*stated_hash, ours);

    let Some(Step::DualBound { terms, .. }) = proof.at(1) else {
        panic!("the verifier's second record is the dual bound");
    };
    assert_eq!(terms.len(), 1);
    assert_eq!(terms[0].0, 0);
    assert_eq!(terms[0].1.to_canonical(), "1");
}

#[test]
fn the_two_readers_refuse_a_reattached_certificate_the_same_way() {
    let bytes = frozen();
    let mut other = INSTANCE.to_vec();
    other.push(b'\n');

    let solver = hc_cert::read::bind(&decode(&bytes).expect("accepted"), &other)
        .expect_err("the solver reader refuses the binding");
    let verifier =
        hc_verify::vhcc::read(&bytes, &other).expect_err("the verifier reader refuses the binding");
    assert_eq!(solver.id.to_string(), verifier.code.text().to_owned());
    assert_eq!(solver.id.to_string(), "HCC-PARSE-03".to_owned());
}
